-- Create "agent_chat_conversations" table
CREATE TABLE "agent"."agent_chat_conversations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "deleted_at" timestamptz NULL, "title" character varying NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, "deleted_by_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "agent_chat_conversations_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_conversations_users_deleter" FOREIGN KEY ("deleted_by_id") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "agent_chat_conversations_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_conversations_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "agentchatconversation_workspace_id_created_by" to table: "agent_chat_conversations"
CREATE INDEX "agentchatconversation_workspace_id_created_by" ON "agent"."agent_chat_conversations" ("workspace_id", "created_by");
-- Create index "agentchatconversation_workspace_id_deleted_at" to table: "agent_chat_conversations"
CREATE INDEX "agentchatconversation_workspace_id_deleted_at" ON "agent"."agent_chat_conversations" ("workspace_id", "deleted_at");
-- Create "agent_chat_messages" table
CREATE TABLE "agent"."agent_chat_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "role" character varying NOT NULL, "content" text NOT NULL DEFAULT '', "parts" jsonb NULL, "draft_status" character varying NOT NULL DEFAULT 'none', "confirmed_transaction_id" bigint NULL, "conversation_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "agent_chat_messages_agent_chat_conversations_messages" FOREIGN KEY ("conversation_id") REFERENCES "agent"."agent_chat_conversations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_messages_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_messages_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_messages_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "agentchatmessage_workspace_id_conversation_id" to table: "agent_chat_messages"
CREATE INDEX "agentchatmessage_workspace_id_conversation_id" ON "agent"."agent_chat_messages" ("workspace_id", "conversation_id");
-- Create "agent_chat_attachments" table
CREATE TABLE "agent"."agent_chat_attachments" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "object_key" character varying NOT NULL, "bucket" character varying NOT NULL, "mime" character varying NOT NULL, "size" bigint NOT NULL, "file_name" character varying NOT NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, "conversation_id" bigint NOT NULL, "message_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "agent_chat_attachments_agent_chat_conversations_conversation" FOREIGN KEY ("conversation_id") REFERENCES "agent"."agent_chat_conversations" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "agent_chat_attachments_agent_chat_messages_attachments" FOREIGN KEY ("message_id") REFERENCES "agent"."agent_chat_messages" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "agent_chat_attachments_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_attachments_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_chat_attachments_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "agentchatattachment_workspace_id_conversation_id" to table: "agent_chat_attachments"
CREATE INDEX "agentchatattachment_workspace_id_conversation_id" ON "agent"."agent_chat_attachments" ("workspace_id", "conversation_id");
-- Create index "agentchatattachment_workspace_id_message_id" to table: "agent_chat_attachments"
CREATE INDEX "agentchatattachment_workspace_id_message_id" ON "agent"."agent_chat_attachments" ("workspace_id", "message_id");
